134:     private function race(array $jobs, array $expected = ['OK', 'OK']): void
135:     {
136:         $barrier = tempnam(sys_get_temp_dir(), 'inventory-race-');
137:         unlink($barrier);
138:         $db = config('database.connections.pgsql');
139:         $environment = ['APP_ENV' => 'testing', 'DB_CONNECTION' => 'pgsql', 'DB_DATABASE' => $db['database'],
140:             'DB_HOST' => $db['host'], 'DB_PORT' => (string) $db['port'], 'DB_USERNAME' => $db['username'],
141:             'DB_PASSWORD' => $db['password'], 'DB_URL' => '', 'CACHE_STORE' => 'array', 'QUEUE_CONNECTION' => 'sync',
142:             'INVENTORY_START_FILE' => $barrier];
143:         $processes = [];
144:         try {
145:             foreach ($jobs as $operation) {
146:                 $script = <<<'PHP'
147: require 'vendor/autoload.php';
148: $app = require 'bootstrap/app.php';
149: $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
150: Illuminate\Support\Facades\DB::statement("SET lock_timeout = '7s'");
151: echo "READY\n";
152: $deadline = microtime(true) + 12;
153: while (!is_file(getenv('INVENTORY_START_FILE'))) {
154:     if (microtime(true) > $deadline) { exit(4); }
155:     usleep(10000);
156: }
157: try {
158: PHP;
159:                 $script .= $operation;
160:                 $script .= <<<'PHP'
161: echo "OK\n";
162: } catch (App\Exceptions\BusinessException $exception) {
163:     echo "REJECTED\n";
164: } catch (Throwable $exception) {
165:     fwrite(STDERR, get_class($exception).': '.$exception->getMessage());
166:     exit(3);
167: }
168: PHP;
169:                 $process = new Process([PHP_BINARY, '-r', $script], base_path(), $environment, timeout: 15);
170:                 $process->start();
171:                 $processes[] = $process;
172:             }
173:             foreach ($processes as $process) {
174:                 $this->assertTrue($process->waitUntil(fn ($type, $output) => str_contains($output, 'READY')), $process->getErrorOutput());
175:             }
176:             touch($barrier);
177:             $results = [];
178:             foreach ($processes as $process) {
179:                 $process->wait();
180:                 $this->assertTrue($process->isSuccessful(), $process->getErrorOutput());
181:                 $results[] = trim(str_replace('READY', '', $process->getOutput()));
182:             }
183:             $this->assertEqualsCanonicalizing($expected, $results);
184:         } finally {
185:             foreach ($processes as $process) {
186:                 if ($process->isRunning()) {
187:                     $process->stop();
188:                 }
189:             }
190:             foreach ([$barrier, $barrier.'.left', $barrier.'.right'] as $path) {
191:                 if (is_file($path)) {
192:                     unlink($path);
193:                 }
194:             }
195:         }
196:     }
