 82:             ->when($filters['location_id'] ?? null, fn ($q, $v) => $q->where('location_id', $v))
 83:             ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
 84:             ->when($filters['product_id'] ?? null, fn ($q, $v) => $q->whereHas('variant', fn ($vq) => $vq->where('product_id', $v)))
 85:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 86:             ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('created_at', '>=', Carbon::parse($v)->startOfDay()))
 87:             ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('created_at', '<', Carbon::parse($v)->addDay()->startOfDay()))
 88:             ->orderByDesc('id')
 89:             ->paginate($filters['per_page'] ?? 15);
 90: 
 91:         return StockMovementResource::collection($movements);
 92:     }
 93: 
 94:     /** تسوية يدوية: كل العناصر في transaction واحدة عبر InventoryService فقط. */
 95:     public function adjustments(StoreAdjustmentRequest $request): JsonResponse
 96:     {
 97:         $movements = $this->inventory->applyAdjustments($request->validated(), $request->user()->id);
 98: 
 99:         return response()->json([
100:             'message' => 'تم تنفيذ التسوية بنجاح',
101:             'data' => StockMovementResource::collection(collect($movements)->each->load(['variant', 'branch', 'location'])),
102:         ], 201);
103:     }
104: } 1: <?php
