23: class PriceListController extends Controller implements HasMiddleware
24: {
25:     public function __construct(private readonly PriceListService $priceLists) {}
26: 
27:     public static function middleware(): array
28:     {
29:         return [
30:             new Middleware('can:price_lists.view', only: ['index', 'show']),
31:             new Middleware('can:price_lists.create', only: ['store']),
32:             new Middleware('can:price_lists.update', only: ['update']),
33:             new Middleware('can:price_lists.delete', only: ['destroy']),
34:             new Middleware('can:price_lists.import', only: ['import']),
35:             new Middleware('can:price_lists.export', only: ['export']),
36:         ];
37:     }
38: 
39:     public function index(Request $request): AnonymousResourceCollection
40:     {
41:         $filters = $request->validate([
42:             'type' => ['nullable', Rule::in(array_column(PriceListType::cases(), 'value'))],
43:             'customer_id' => ['nullable', 'integer', 'min:1'],
44:             'customer_group_id' => ['nullable', 'integer', 'min:1'],
45:             'branch_id' => ['nullable', 'integer', 'min:1'],
46:             'is_active' => ['nullable', 'boolean'],
47:             'search' => ['nullable', 'string', 'max:100'],
48:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
49:         ]);
50: 
51:         return PriceListResource::collection($this->priceLists->paginate($filters));
52:     }
53: 
54:     public function store(StorePriceListRequest $request): JsonResponse
55:     {
56:         $priceList = $this->priceLists->create($request->validated());
57: 
58:         return (new PriceListResource($priceList))
59:             ->additional(['message' => 'تم إنشاء قائمة الأسعار بنجاح'])
60:             ->response()
61:             ->setStatusCode(201);
62:     }
63: 
64:     public function show(PriceList $priceList): PriceListResource
65:     {
66:         return new PriceListResource($this->priceLists->find($priceList->id));
67:     }
68: 
69:     public function update(UpdatePriceListRequest $request, PriceList $priceList): PriceListResource
70:     {
71:         return new PriceListResource($this->priceLists->update($priceList, $request->validated()));
72:     }
73: 
74:     public function destroy(PriceList $priceList): JsonResponse
75:     {
76:         $this->priceLists->delete($priceList);
77: 
78:         return response()->json(['message' => 'تم حذف قائمة الأسعار بنجاح']);
79:     }
80: 
81:     /** استيراد أسعار من CSV (updateOrCreate على القائمة/المتغير/حد الكمية). */
82:     public function import(ImportPriceListItemsRequest $request, PriceList $priceList): JsonResponse
83:     {
84:         $report = $this->priceLists->importCsv($priceList, $request->file('file'));
85: 
86:         return response()->json([
87:             'message' => 'تم تنفيذ الاستيراد',
88:             'data' => $report,
89:         ]);
90:     }
91: 
92:     /** تصدير عناصر القائمة كملف CSV قابل لإعادة الاستيراد. */
93:     public function export(PriceList $priceList): StreamedResponse
94:     {
95:         return $this->priceLists->exportCsv($priceList);
96:     }
97: } 1: <?php
