 5: namespace App\Services;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use App\Models\CustomerGroup;
 9: use Illuminate\Contracts\Pagination\LengthAwarePaginator;
10: 
11: class CustomerGroupService
12: {
13:     public function paginate(array $filters): LengthAwarePaginator
14:     {
15:         return CustomerGroup::query()
16:             ->withCount('customers')
17:             ->when($filters['search'] ?? null, fn ($q, $v) => $q->where(fn ($search) => $search
18:                 ->whereLike('name', '%'.SearchTerm::escape($v).'%', caseSensitive: false)
19:                 ->orWhereLike('code', '%'.SearchTerm::escape($v).'%', caseSensitive: false)))
20:             ->when(array_key_exists('is_active', $filters) && $filters['is_active'] !== null, fn ($q) => $q->where('is_active', $filters['is_active']))
21:             ->orderBy('name')
22:             ->orderBy('id')
23:             ->paginate($filters['per_page'] ?? 15);
24:     }
25: 
26:     public function create(array $data): CustomerGroup
27:     {
28:         $data = array_filter($data, fn ($value, $key) => $value !== null || ! in_array($key, ['discount_percentage', 'is_active'], true), ARRAY_FILTER_USE_BOTH);
29: 
30:         return CustomerGroup::query()->create($data);
31:     }
32: 
33:     public function update(CustomerGroup $group, array $data): CustomerGroup
34:     {
35:         $group->update($data);
36: 
37:         return $group;
38:     }
39: 
40:     public function delete(CustomerGroup $group): void
41:     {
42:         if ($group->customers()->exists()) {
43:             throw new BusinessException('لا يمكن حذف مجموعة مرتبطة بعملاء؛ انقل العملاء أولًا أو عطّل المجموعة.');
44:         }
45: 
46:         if ($group->priceLists()->exists()) {
47:             throw new BusinessException('لا يمكن حذف مجموعة مرتبطة بقوائم أسعار.');
48:         }
49: 
50:         $group->delete();
51:     }
52: }  1: <?php
