  5: namespace App\Services;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Location;
 11: use App\Models\StockLevel;
 12: use App\Models\StockMovement;
 13: use Illuminate\Support\Collection;
 14: use Illuminate\Support\Facades\DB;
 15: 
 16: /**
 17:  * القلب النابض للمخزون — الطريق الوحيد لتغيير أي رصيد في النظام.
 18:  *
 19:  * قاعدة صارمة: ممنوع تعديل stock_levels من أي Controller أو Model آخر.
 20:  * كل تغيير يمر من هنا: تسجيل حركة في دفتر الأستاذ (stock_movements) أولًا،
 21:  * ثم تحديث الرصيد — داخل نفس الـ transaction ومع قفل الصف.
 22:  */
 23: class InventoryService
 24: {
 25:     public function __construct(private readonly SettingService $settings) {}
 26: 
 27:     /**
 28:      * الدالة المركزية الوحيدة لتغيير أي رصيد في النظام.
 29:      *
 30:      * @param  array{product_variant_id: int, branch_id: int, location_id?: int|null, type: StockMovementType|string, affected_bucket: StockBucket|string, quantity: float|int|string, unit_cost?: float|null, reference_type?: string|null, reference_id?: int|null, created_by?: int|null, notes?: string|null}  $data
 31:      */
 32:     public function recordMovement(array $data): StockMovement
 33:     {
 34:         return DB::transaction(function () use ($data): StockMovement {
 35:             $rawQty = $data['quantity'];
 36:             if (! is_numeric($rawQty) || ! is_finite((float) $rawQty) || abs((float) $rawQty) > 99999999.9999) {
 37:                 throw new BusinessException('كمية الحركة غير صالحة.');
 38:             }
 39:             // Work in ten-thousandths to avoid floating point residues at zero.
 40:             $units = (int) round((float) $rawQty * 10000);
 41:             $qty = $units / 10000;
 42: 
 43:             if ($units === 0) {
 44:                 throw new BusinessException('كمية الحركة يجب ألا تساوي صفرًا.');
 45:             }
 46: 
 47:             $type = $data['type'] instanceof StockMovementType ? $data['type'] : StockMovementType::from($data['type']);
 48:             $bucket = $data['affected_bucket'] instanceof StockBucket ? $data['affected_bucket'] : StockBucket::from($data['affected_bucket']);
 49:             $this->assertValidMovementSemantics($type, $bucket, $units);
 50:             $locationId = $data['location_id'] ?? null;
 51:             if ($locationId !== null && ! Location::query()->whereKey($locationId)->where('branch_id', $data['branch_id'])->exists()) {
 52:                 throw new BusinessException('الموقع لا يتبع الفرع المحدد.');
 53:             }
 54: 
 55:             $levels = $this->lockLevels([[
 56:                 'product_variant_id' => $data['product_variant_id'],
 57:                 'branch_id' => $data['branch_id'],
 58:                 'location_id' => $locationId,
 59:             ]]);
 60: 
 61:             $stock = $levels->first();
 62: 
 63:             $bucketKey = $bucket->value;
 64:             $before = (float) $stock->{$bucketKey};
 65:             $afterUnits = (int) round($before * 10000) + $units;
 66:             $after = $afterUnits / 10000;
 67:             if ($afterUnits > 999999999999) {
 68:                 throw new BusinessException('الرصيد يتجاوز الحد المسموح.');
 69:             }
 70: 
 71:             // 2. التحقق: الرصيد المستهدف لا ينزل تحت الصفر
 72:             if ($after < 0) {
 73:                 throw new BusinessException("الرصيد غير كافٍ في ({$bucketKey}) لإتمام العملية.");
 74:             }
 75: 
 76:             // 3. التحقق: الكمية المتاحة للبيع لا تصبح سالبة بعد الحركة
 77:             //    (يغطي حجز/تالف جديد أكبر من المتاح، وسحب فعلي يبتلع محجوزًا أو تالفًا)
 78:             $onHand = $bucket === StockBucket::OnHand ? $after : (float) $stock->on_hand;
 79:             $reserved = $bucket === StockBucket::Reserved ? $after : (float) $stock->reserved;
 80:             $damaged = $bucket === StockBucket::Damaged ? $after : (float) $stock->damaged;
 81:             $availableAfter = (int) round($onHand * 10000) - (int) round($reserved * 10000) - (int) round($damaged * 10000);
 82: 
 83:             if ($availableAfter < 0) {
 84:                 $availableNow = (float) $stock->on_hand - (float) $stock->reserved - (float) $stock->damaged;
 85: 
 86:                 throw new BusinessException("الكمية المتاحة للبيع ({$availableNow}) غير كافية لإتمام العملية.");
 87:             }
 88: 
 89:             // 4. تسجيل الحركة في دفتر الأستاذ (Ledger)
 90:             $movement = StockMovement::query()->create([
 91:                 'reference_number' => $this->settings->generateNextNumber('movement'),
 92:                 'product_variant_id' => $data['product_variant_id'],
 93:                 'branch_id' => $data['branch_id'],
 94:                 'location_id' => $locationId,
 95:                 'type' => $type,
 96:                 'affected_bucket' => $bucket,
 97:                 'quantity' => $qty,
 98:                 'balance_before' => $before,
 99:                 'balance_after' => $after,
100:                 'unit_cost' => $data['unit_cost'] ?? null,
101:                 'reference_type' => $data['reference_type'] ?? null,
102:                 'reference_id' => $data['reference_id'] ?? null,
103:                 'created_by' => $data['created_by'] ?? auth()->id(),
104:                 'notes' => $data['notes'] ?? null,
105:             ]);
106: 
107:             // 5. تحديث جدول الأرصدة من واقع الحركة
108:             $stock->{$bucketKey} = $after;
109:             $stock->save();
110: 
111:             return $movement;
112:         });
113:     }
114: 
115:     /**
116:      * تسوية يدوية متعددة العناصر داخل transaction واحدة (أي فشل يلغي الكل).
117:      *
118:      * @param  array{branch_id: int, location_id?: int|null, items: list<array{product_variant_id: int, adjustment_type: string, quantity: float|int|string, reason?: string|null}>}  $payload
119:      * @return list<StockMovement>
120:      */
121:     public function applyAdjustments(array $payload, int $userId): array
122:     {
123:         return DB::transaction(function () use ($payload, $userId): array {
124:             app(BranchAccess::class)->assertBranch($userId, (int) $payload['branch_id']);
125:             $this->lockLevels(array_map(fn ($item) => [
126:                 'product_variant_id' => $item['product_variant_id'],
127:                 'branch_id' => $payload['branch_id'],
128:                 'location_id' => $payload['location_id'] ?? null,
129:             ], $payload['items']));
130:             $movements = [];
131: 
132:             foreach ($payload['items'] as $item) {
133:                 if (in_array($item['adjustment_type'], ['write_off_damaged', 'restore_damaged'], true)) {
134:                     $base = [
135:                         'product_variant_id' => $item['product_variant_id'],
136:                         'branch_id' => $payload['branch_id'], 'location_id' => $payload['location_id'] ?? null,
137:                         'created_by' => $userId, 'notes' => $item['reason'] ?? null,
138:                         'quantity' => -abs((float) $item['quantity']),
139:                     ];
140:                     $movements[] = $this->recordMovement([...$base, 'type' => StockMovementType::DamageRelease, 'affected_bucket' => StockBucket::Damaged]);
141:                     if ($item['adjustment_type'] === 'write_off_damaged') {
142:                         $movements[] = $this->recordMovement([...$base, 'type' => StockMovementType::DamageWriteOff, 'affected_bucket' => StockBucket::OnHand]);
143:                     }
144: 
145:                     continue;
146:                 }
147:                 [$type, $bucket, $sign] = match ($item['adjustment_type']) {
148:                     'increase' => [StockMovementType::AdjustmentIn, StockBucket::OnHand, 1],
149:                     'decrease' => [StockMovementType::AdjustmentOut, StockBucket::OnHand, -1],
150:                     'mark_damaged' => [StockMovementType::Damage, StockBucket::Damaged, 1],
151:                     default => throw new BusinessException('نوع تسوية غير معروف: '.$item['adjustment_type']),
152:                 };
153: 
154:                 $movements[] = $this->recordMovement([
155:                     'product_variant_id' => $item['product_variant_id'],
156:                     'branch_id' => $payload['branch_id'],
157:                     'location_id' => $payload['location_id'] ?? null,
158:                     'type' => $type,
159:                     'affected_bucket' => $bucket,
160:                     'quantity' => $sign * abs((float) $item['quantity']),
161:                     'created_by' => $userId,
162:                     'notes' => $item['reason'] ?? null,
163:                 ]);
164:             }
165: 
166:             return $movements;
167:         });
168:     }
