170:     /** الرصيد الحالي لمتغير في فرع/موقع (للقطات الجرد ونحوها) — قراءة فقط. */
171:     public function levelFor(int $variantId, int $branchId, ?int $locationId): ?StockLevel
172:     {
173:         return StockLevel::query()
174:             ->where('product_variant_id', $variantId)
175:             ->where('branch_id', $branchId)
176:             ->where('location_id', $locationId)
177:             ->first();
178:     }
179: 
180:     /** Acquire every stock key before a multi-item operation, in one global order. */
181:     public function lockLevels(array $keys): Collection
182:     {
183:         if (DB::transactionLevel() === 0) {
184:             throw new \LogicException('Stock locks require an active transaction.');
185:         }
186:         $keys = collect($keys)->unique(fn ($key) => $this->levelKey($key))
187:             ->sortBy(fn ($key) => [(int) $key['branch_id'], (int) ($key['location_id'] ?? 0), (int) $key['product_variant_id']]);
188:         if ($keys->isEmpty()) {
189:             return collect();
190:         }
191:         $now = now();
192:         DB::table('stock_levels')->insertOrIgnore($keys->map(fn ($key) => [
193:             'product_variant_id' => $key['product_variant_id'], 'branch_id' => $key['branch_id'],
194:             'location_id' => $key['location_id'] ?? null, 'created_at' => $now, 'updated_at' => $now,
195:         ])->values()->all());
196: 
197:         $levels = StockLevel::query()->where(function ($query) use ($keys): void {
198:             foreach ($keys->groupBy(fn ($key) => $key['branch_id'].':'.($key['location_id'] ?? 0)) as $group) {
199:                 $identity = $group->first();
200:                 $query->orWhere(fn ($scope) => $scope->where('branch_id', $identity['branch_id'])
201:                     ->where('location_id', $identity['location_id'] ?? null)
202:                     ->whereIn('product_variant_id', $group->pluck('product_variant_id')->all()));
203:             }
204:         })->orderBy('branch_id')->orderByRaw('location_id ASC NULLS FIRST')->orderBy('product_variant_id')
205:             ->lockForUpdate()->get()->keyBy(fn ($stock) => $this->levelKey($stock->getAttributes()));
206: 
207:         return $levels;
208:     }
209: 
210:     public function levelKey(array $key): string
211:     {
212:         return $key['branch_id'].':'.($key['location_id'] ?? 0).':'.$key['product_variant_id'];
213:     }
214: 
215:     private function assertValidMovementSemantics(StockMovementType $type, StockBucket $bucket, int $units): void
216:     {
217:         [$allowed, $positive] = match ($type) {
218:             StockMovementType::PurchaseReceipt, StockMovementType::SaleReturn,
219:             StockMovementType::AdjustmentIn, StockMovementType::StocktakeGain, StockMovementType::TransferIn => [[StockBucket::OnHand], true],
220:             StockMovementType::Sale, StockMovementType::AdjustmentOut,
221:             StockMovementType::StocktakeLoss, StockMovementType::TransferOut,
222:             StockMovementType::DamageWriteOff => [[StockBucket::OnHand], false],
223:             StockMovementType::Damage => [[StockBucket::Damaged], true],
224:             StockMovementType::DamageRelease => [[StockBucket::Damaged], false],
225:             StockMovementType::Reserve => [[StockBucket::Reserved], true],
226:             StockMovementType::ReleaseReserve => [[StockBucket::Reserved], false],
227:             StockMovementType::TransferInTransit => [[StockBucket::InTransit], true],
228:             StockMovementType::TransferTransitRelease, StockMovementType::TransferShortage => [[StockBucket::InTransit], false],
229:         };
230:         if (! in_array($bucket, $allowed, true) || ($units > 0) !== $positive) {
231:             throw new BusinessException('نوع الحركة لا يطابق وعاء المخزون أو اتجاه الكمية.');
232:         }
233:     }
