 23: class PriceListService
 24: {
 25:     public function paginate(array $filters): LengthAwarePaginator
 26:     {
 27:         return PriceList::query()
 28:             ->with(['customer', 'customerGroup', 'branch'])
 29:             ->withCount('items')
 30:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 31:             ->when($filters['customer_id'] ?? null, fn ($q, $v) => $q->where('customer_id', $v))
 32:             ->when($filters['customer_group_id'] ?? null, fn ($q, $v) => $q->where('customer_group_id', $v))
 33:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 34:             ->when(array_key_exists('is_active', $filters) && $filters['is_active'] !== null, fn ($q) => $q->where('is_active', $filters['is_active']))
 35:             ->when($filters['search'] ?? null, fn ($q, $v) => $q->whereLike('name', '%'.SearchTerm::escape($v).'%', caseSensitive: false))
 36:             ->orderByDesc('priority')
 37:             ->orderByDesc('id')
 38:             ->paginate($filters['per_page'] ?? 15);
 39:     }
