 49:     public function create(array $data): PriceList
 50:     {
 51:         $data = array_filter($data, fn ($value, $key) => $value !== null || ! in_array($key, ['currency', 'priority', 'is_active'], true), ARRAY_FILTER_USE_BOTH);
 52:         $this->validateDates($data);
 53:         $data = $this->withValidOwner($data);
 54: 
 55:         return PriceList::query()->create($data)->load(['customer', 'customerGroup', 'branch']);
 56:     }
 57: 
 58:     public function update(PriceList $priceList, array $data): PriceList
 59:     {
 60:         return DB::transaction(function () use ($priceList, $data): PriceList {
 61:             $priceList = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
 62:             $this->validateDates($data, $priceList);
 63:             $data = $this->withValidOwner($data, $priceList);
 64:             $priceList->update($data);
 65: 
 66:             return $priceList->load(['customer', 'customerGroup', 'branch']);
 67:         });
 68:     }
