 70:     private function withValidOwner(array $data, ?PriceList $priceList = null): array
 71:     {
 72:         // فرض ربط النوع بالمالك على الحالة النهائية: النوع الخاص بعميل لازم له عميل،
 73:         // والخاص بمجموعة لازم له مجموعة، وأي نوع تاني بيصفّي الحقلين تلقائيًا
 74:         $type = $data['type'] ?? $priceList?->type;
 75:         $typeValue = $type instanceof PriceListType ? $type->value : $type;
 76: 
 77:         if ($typeValue === PriceListType::CustomerSpecific->value) {
 78:             $customerId = array_key_exists('customer_id', $data) ? $data['customer_id'] : $priceList?->customer_id;
 79:             if ($customerId === null) {
 80:                 throw new BusinessException('قائمة الأسعار الخاصة بعميل تتطلب تحديد العميل.');
 81:             }
 82:             $data['customer_id'] = $customerId;
 83:             $data['customer_group_id'] = null;
 84:         } elseif ($typeValue === PriceListType::CustomerGroup->value) {
 85:             $groupId = array_key_exists('customer_group_id', $data) ? $data['customer_group_id'] : $priceList?->customer_group_id;
 86:             if ($groupId === null) {
 87:                 throw new BusinessException('قائمة أسعار المجموعة تتطلب تحديد مجموعة العملاء.');
 88:             }
 89:             $data['customer_group_id'] = $groupId;
 90:             $data['customer_id'] = null;
 91:         } else {
 92:             $data['customer_id'] = null;
 93:             $data['customer_group_id'] = null;
 94:         }
 95: 
 96:         return $data;
 97:     }
