117:     public function createItem(PriceList $priceList, array $data): PriceListItem
118:     {
119:         return DB::transaction(function () use ($priceList, $data): PriceListItem {
120:             $priceList = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
121:             $data['min_qty'] = $data['min_qty'] ?? 1;
122:             $this->validateDates($data);
123:             $this->assertNoDuplicateTier($priceList, (int) $data['product_variant_id'], (float) $data['min_qty']);
