133:             $item = PriceListItem::query()->lockForUpdate()->findOrFail($item->id);
134:             $this->validateDates($data, $item);
135:             if (isset($data['product_variant_id']) || isset($data['min_qty'])) {
136:                 $this->assertNoDuplicateTier(
137:                     $item->priceList,
138:                     (int) ($data['product_variant_id'] ?? $item->product_variant_id),
139:                     (float) ($data['min_qty'] ?? $item->min_qty),
140:                     $item->id,
141:                 );
142:             }
143: 
144:             $item->update($data);
145: 
146:             return $item->load('variant.product');
