155:     private function assertNoDuplicateTier(PriceList $priceList, int $variantId, float $minQty, ?int $ignoreItemId = null): void
156:     {
157:         $exists = $priceList->items()
158:             ->where('product_variant_id', $variantId)
159:             ->where('min_qty', $minQty)
160:             ->when($ignoreItemId !== null, fn ($q) => $q->whereKeyNot($ignoreItemId))
161:             ->exists();
162: 
163:         if ($exists) {
164:             throw new BusinessException('توجد شريحة بنفس المتغير وحد الكمية داخل هذه القائمة بالفعل.');
