170:     /** تصدير عناصر القائمة كـ CSV بنفس أعمدة الاستيراد عشان إعادة الاستيراد تشتغل. */
171:     public function exportCsv(PriceList $priceList): StreamedResponse
172:     {
173:         return response()->streamDownload(function () use ($priceList): void {
174:             $handle = fopen('php://output', 'w');
175:             try {
176:                 fputcsv($handle, ['sku', 'variant_id', 'product_name', 'min_qty', 'price', 'starts_at', 'ends_at']);
177: 
178:                 $priceList->items()
179:                     ->with(['variant.product' => fn ($query) => $query->withTrashed()])
180:                     ->chunkById(500, function ($items) use ($handle): void {
181:                         foreach ($items as $item) {
182:                             fputcsv($handle, [
183:                                 $this->csvText($item->variant?->sku ?? ''),
184:                                 $item->product_variant_id,
185:                                 $this->csvText($item->variant?->product?->name_ar ?? ''),
186:                                 $item->min_qty,
187:                                 $item->price,
188:                                 $item->starts_at?->format('Y-m-d H:i:s'),
189:                                 $item->ends_at?->format('Y-m-d H:i:s'),
190:                             ]);
191:                         }
192:                     });
193: 
194:             } finally {
195:                 fclose($handle);
196:             }
197:         }, 'price-list-'.$priceList->id.'.csv', ['Content-Type' => 'text/csv; charset=UTF-8']);
198:     }
