205:     /**
206:      * استيراد CSV: كل صف بيحدّث أو ينشئ عنصرًا بمفتاح (القائمة، المتغير، min_qty)
207:      * داخل transaction واحدة. أخطاء الصفوف الفردية بتتجمع في التقرير من غير ما توقف الكل.
208:      *
209:      * @return array{created: int, updated: int, skipped: int, errors: list<array{line: int, message: string}>}
210:      */
211:     public function importCsv(PriceList $priceList, UploadedFile $file): array
212:     {
213:         $handle = fopen($file->getRealPath(), 'r');
214:         if ($handle === false) {
215:             throw new BusinessException('تعذرت قراءة ملف الاستيراد.');
216:         }
217:         try {
218:             $header = fgetcsv($handle);
219:             if ($header === false) {
220:                 throw new BusinessException('ملف الاستيراد فارغ.');
221:             }
222:             $header[0] = preg_replace('/^\xEF\xBB\xBF/', '', (string) $header[0]);
223:             $columns = array_map(fn ($h) => strtolower(trim((string) $h)), $header);
224:             $index = array_flip($columns);
225:             if (count($index) !== count($columns) || ! isset($index['price']) || (! isset($index['variant_id']) && ! isset($index['sku']))) {
226:                 throw new BusinessException('يجب أن يحتوي الملف على price وsku أو variant_id، دون أعمدة مكررة.');
227:             }
228:             $rows = [];
229:             $line = 1;
230:             while (($row = fgetcsv($handle)) !== false) {
231:                 $line++;
232:                 if ($line > 10000) {
233:                     throw new BusinessException('عدد أسطر الملف يتجاوز الحد المسموح.');
234:                 }
235:                 if ($row === [null] || trim(implode('', array_map('strval', $row))) === '') {
236:                     continue;
237:                 }
238:                 if (count($rows) >= 2000) {
239:                     throw new BusinessException('الحد الأقصى للاستيراد المتزامن 2000 صف؛ قسّم الملف إلى أجزاء أصغر.');
240:                 }
241:                 $get = fn (string $key) => isset($index[$key]) ? trim((string) ($row[$index[$key]] ?? '')) : '';
242:                 $rows[] = ['line' => $line, 'variant_id' => $get('variant_id'), 'sku' => $get('sku'),
243:                     'price' => $get('price'), 'min_qty' => $get('min_qty') === '' ? '1' : $get('min_qty'),
244:                     'starts_at' => $get('starts_at') === '' ? null : $get('starts_at'),
245:                     'ends_at' => $get('ends_at') === '' ? null : $get('ends_at')];
246:             }
247:         } finally {
248:             fclose($handle);
249:         }
250: 
251:         $ids = array_values(array_filter(array_map(fn ($row) => filter_var($row['variant_id'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]), $rows)));
252:         $skus = [];
253:         foreach ($rows as $row) {
254:             $skus[] = $row['sku'];
255:             $skus[] = $this->unescapeCsvText($row['sku']);
256:         }
257:         $variants = ProductVariant::query()->where('is_active', true)
258:             ->where(fn ($q) => $q->whereIn('id', $ids)->orWhereIn('sku', array_unique($skus)))->get();
259:         $byId = $variants->keyBy('id');
260:         $bySku = $variants->keyBy('sku');
261:         $report = ['created' => 0, 'updated' => 0, 'skipped' => 0, 'errors' => []];
262:         $valid = [];
263:         foreach ($rows as $row) {
264:             try {
265:                 $variant = $row['variant_id'] !== ''
266:                     ? $byId->get(filter_var($row['variant_id'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: 0)
267:                     : ($bySku->get($row['sku']) ?? $bySku->get($this->unescapeCsvText($row['sku'])));
268:                 if ($variant === null || ($row['sku'] !== '' && $row['sku'] !== $variant->sku && $row['sku'] !== $this->csvText($variant->sku))) {
269:                     throw new BusinessException('الصنف غير موجود أو يوجد تعارض بين sku وvariant_id.');
270:                 }
271:                 $validator = Validator::make($row, [
272:                     'price' => ['required', 'numeric', 'decimal:0,4', 'min:0', 'max:99999999.9999'],
273:                     'min_qty' => ['required', 'numeric', 'decimal:0,4', 'gt:0', 'max:99999999.9999'],
274:                     'starts_at' => ['nullable', 'date'], 'ends_at' => ['nullable', 'date'],
275:                 ]);
276:                 if ($validator->fails()) {
277:                     throw new BusinessException($validator->errors()->first());
278:                 }
279:                 $row['starts_at'] = $this->parseDate($row['starts_at'] ?? '');
280:                 $row['ends_at'] = $this->parseDate($row['ends_at'] ?? '');
281:                 $this->validateDates($row);
282:                 $valid[] = [...$row, 'product_variant_id' => $variant->id];
283:             } catch (BusinessException $exception) {
284:                 $report['skipped']++;
285:                 $report['errors'][] = ['line' => $row['line'], 'message' => $exception->getMessage()];
286:             }
287:         }
288:         DB::transaction(function () use ($valid, $priceList, &$report): void {
289:             PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
290:             foreach ($valid as $row) {
291:                 $item = PriceListItem::query()->updateOrCreate([
292:                     'price_list_id' => $priceList->id, 'product_variant_id' => $row['product_variant_id'], 'min_qty' => $row['min_qty'],
293:                 ], ['price' => $row['price'], 'starts_at' => $row['starts_at'], 'ends_at' => $row['ends_at']]);
294:                 $item->wasRecentlyCreated ? $report['created']++ : $report['updated']++;
295:             }
296:         });
297: 
298:         return $report;
299:     }
