  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Enums\PriceListType;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\Customer;
 12: use App\Models\PriceListItem;
 13: use App\Models\ProductVariant;
 14: use Carbon\Carbon;
 15: use Illuminate\Database\Eloquent\Builder;
 16: 
 17: /**
 18:  * محرك التسعير المركزي — يُستدعى من المتجر والجملة والـ POS ولوحة الإدارة.
 19:  *
 20:  * شجرة الأولويات:
 21:  * 1. سعر خاص بالعميل (customer_specific)
 22:  * 2. سعر مجموعة العميل (customer_group)
 23:  * 3. قائمة النوع (wholesale/distributor للمعتمدين فقط، وإلا retail)
 24:  * 4. السعر الأساسي للمتغير (base_price، المتوافق مع retail_price من المرحلة 2).
 25:  *
 26:  * داخل كل مستوى: القائمة المخصصة للفرع أولًا، ثم أعلى شريحة كمية محققة،
 27:  * ثم أولوية القائمة، ثم السعر الأقل.
 28:  */
 29: class PricingService
 30: {
 31:     /**
 32:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
 33:      */
 34:     public function resolve(
 35:         ProductVariant $variant,
 36:         ?Customer $customer = null,
 37:         float $qty = 1,
 38:         ?int $branchId = null,
 39:     ): array {
 40:         if (! is_finite($qty) || $qty <= 0) {
 41:             throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
 42:         }
 43:         $now = Carbon::now();
 44: 
 45:         $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
 46:         $channel = $this->channelFor($customer);
 47:         $eligibleCustomer = $customer !== null && $customer->status === CustomerStatus::Approved;
 48: 
 49:         // الأولوية 1: سعر خاص بالعميل
 50:         if ($eligibleCustomer) {
 51:             $item = $this->ordered((clone $baseQuery)
 52:                 ->where('price_lists.type', PriceListType::CustomerSpecific)
 53:                 ->where('price_lists.customer_id', $customer->id)
 54:             )->first();
 55: 
 56:             if ($item !== null) {
 57:                 return $this->formatResponse((float) $item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);
 58:             }
 59:         }
 60: 
 61:         // الأولوية 2: سعر مجموعة العميل
 62:         $group = $eligibleCustomer ? $customer->customerGroup()->where('is_active', true)->first() : null;
 63:         if ($group !== null) {
 64:             $item = $this->ordered((clone $baseQuery)
 65:                 ->where('price_lists.type', PriceListType::CustomerGroup)
 66:                 ->where('price_lists.customer_group_id', $group->id)
 67:             )->first();
 68: 
 69:             if ($item !== null) {
 70:                 return $this->formatResponse((float) $item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);
 71:             }
 72:             // Default group discount is a fallback at group priority, applied once to base price.
 73:             if ((float) $group->discount_percentage > 0) {
 74:                 return $this->formatResponse((float) $variant->base_price * (1 - (float) $group->discount_percentage / 100), 'customer_group_discount', null, $variant, $channel);
 75:             }
 76:         }
 77: 
 78:         // الأولوية 3: قائمة نوع العميل (أو القطاعي افتراضيًا)
 79:         $item = $this->ordered((clone $baseQuery)
 80:             ->where('price_lists.type', $channel)
 81:         )->first();
 82: 
 83:         if ($item !== null) {
 84:             return $this->formatResponse((float) $item->price, $channel->value, (int) $item->price_list_id, $variant, $channel);
 85:         }
 86: 
 87:         // الأولوية 4: السعر الأساسي الموحد؛ أسعار الجملة والموزعين تأتي من القوائم.
 88:         return $this->formatResponse($this->basePrice($variant, $channel), 'base_price', null, $variant, $channel);
 89:     }
 90: 
 91:     /** قناة التسعير: الجملة/الموزع للحسابات المعتمدة فقط، وغير ذلك قطاعي. */
 92:     private function channelFor(?Customer $customer): PriceListType
 93:     {
 94:         if ($customer !== null
 95:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
 96:             && $customer->status === CustomerStatus::Approved) {
 97:             return PriceListType::from($customer->type->value);
 98:         }
 99: 
100:         return PriceListType::Retail;
101:     }
102: 
103:     private function basePrice(ProductVariant $variant, PriceListType $channel): float
104:     {
105:         return (float) $variant->base_price;
106:     }
107: 
108:     /** كل عناصر التسعير السارية لهذا المتغير والكمية والفرع والوقت. */
109:     private function eligibleItems(ProductVariant $variant, float $qty, ?int $branchId, Carbon $now): Builder
110:     {
111:         return PriceListItem::query()
112:             ->select('price_list_items.*')
113:             ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
114:             ->where('price_lists.is_active', true)
115:             ->where('price_list_items.product_variant_id', $variant->id)
116:             ->where('price_list_items.min_qty', '<=', $qty)
117:             ->where(fn ($q) => $q->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', $now))
118:             ->where(fn ($q) => $q->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', $now))
119:             ->where(fn ($q) => $q->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', $now))
120:             ->where(fn ($q) => $q->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', $now))
121:             ->where(function ($q) use ($branchId): void {
122:                 $q->whereNull('price_lists.branch_id');
123:                 if ($branchId !== null) {
124:                     $q->orWhere('price_lists.branch_id', $branchId);
125:                 }
126:             });
127:     }
128: 
129:     /** ترتيب داخل المستوى الواحد: فرع مخصص أولًا، أعلى شريحة، أعلى أولوية، أقل سعر. */
130:     private function ordered(Builder $query): Builder
131:     {
132:         return $query
133:             ->orderByRaw('price_lists.branch_id IS NULL ASC')
134:             ->orderByDesc('price_list_items.min_qty')
135:             ->orderByDesc('price_lists.priority')
136:             ->orderBy('price_list_items.price');
137:     }
138: 
139:     /**
140:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
141:      */
142:     private function formatResponse(float $unitPrice, string $source, ?int $priceListId, ProductVariant $variant, PriceListType $channel): array
143:     {
144:         return [
145:             'unit_price' => round($unitPrice, 2),
146:             'base_price' => round($this->basePrice($variant, $channel), 2),
147:             'source' => $source,
148:             'price_list_id' => $priceListId,
149:         ];
150:     }
