 17: /**
 18:  * جلسات الجرد الفعلي. لقطة system_qty بتتاخد من stock_levels وقت إنشاء العنصر،
 19:  * والاعتماد بيحوّل الفروق لحركات دفتر (فائض/عجز) عبر InventoryService فقط،
 20:  * وبعد الاعتماد الجلسة بتتقفل نهائيًا.
 21:  */
 22: class StocktakeService
 23: {
 24:     public function __construct(
 25:         private readonly InventoryService $inventory,
 26:         private readonly SettingService $settings,
 27:     ) {}
 28: 
 29:     public function paginate(array $filters): LengthAwarePaginator
 30:     {
 31:         return Stocktake::query()
 32:             ->when($filters['staff_branch_id'] ?? null, fn ($q, $branch) => $q->where('branch_id', $branch))
 33:             ->with(['branch', 'location', 'creator'])
 34:             ->withCount('items')
 35:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 36:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
 37:             ->orderByDesc('id')
 38:             ->paginate($filters['per_page'] ?? 15);
 39:     }
 40: 
 41:     public function find(int $id): Stocktake
 42:     {
 43:         return Stocktake::query()
 44:             ->with(['items.variant', 'branch', 'location', 'creator', 'approver'])
 45:             ->findOrFail($id);
 46:     }
 47: 
 48:     public function create(array $data, int $userId): Stocktake
 49:     {
 50:         return DB::transaction(function () use ($data, $userId): Stocktake {
 51:             app(BranchAccess::class)->assertBranch($userId, (int) $data['branch_id']);
 52:             $stocktake = Stocktake::query()->create([
 53:                 'stocktake_number' => $this->settings->generateNextNumber('stocktake'),
 54:                 'branch_id' => $data['branch_id'],
 55:                 'location_id' => $data['location_id'] ?? null,
 56:                 'status' => StocktakeStatus::Draft,
 57:                 'created_by' => $userId,
 58:                 'notes' => $data['notes'] ?? null,
 59:             ]);
 60: 
 61:             $this->syncItems($stocktake, $data['items'] ?? []);
 62: 
 63:             return $stocktake->load(['items.variant', 'branch', 'location', 'creator']);
 64:         });
 65:     }
 66: 
 67:     public function update(Stocktake $stocktake, array $data, int $userId): Stocktake
 68:     {
 69:         return DB::transaction(function () use ($stocktake, $data, $userId): Stocktake {
 70:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
 71:             $this->assertEditable($stocktake);
 72:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
 73:             app(BranchAccess::class)->assertBranch($userId, (int) ($data['branch_id'] ?? $stocktake->branch_id));
 74: 
 75:             $branchId = $data['branch_id'] ?? $stocktake->branch_id;
 76:             $locationId = array_key_exists('location_id', $data) ? $data['location_id'] : $stocktake->location_id;
 77:             if ($locationId !== null && ! Location::query()->whereKey($locationId)->where('branch_id', $branchId)->exists()) {
 78:                 throw new BusinessException('موقع الجرد لا يتبع الفرع المحدد.');
 79:             }
 80:             if (((int) $branchId !== $stocktake->branch_id || ($locationId === null ? null : (int) $locationId) !== $stocktake->location_id)
 81:                 && ! array_key_exists('items', $data) && $stocktake->items()->exists()) {
 82:                 throw new BusinessException('تغيير نطاق الجرد يتطلب إعادة إرسال العناصر والعد الفعلي.');
 83:             }
 84: 
 85:             if (isset($data['status'])) {
 86:                 $target = StocktakeStatus::from($data['status']);
 87:                 $allowed = match ($stocktake->status) {
 88:                     StocktakeStatus::Draft => [StocktakeStatus::InProgress, StocktakeStatus::Cancelled],
 89:                     StocktakeStatus::InProgress => [StocktakeStatus::Cancelled],
 90:                     default => [],
 91:                 };
 92: 
 93:                 if (! in_array($target, $allowed, true)) {
 94:                     throw new BusinessException("لا يمكن نقل الجرد من حالة {$stocktake->status->value} إلى {$target->value}.");
 95:                 }
 96: 
 97:                 $stocktake->status = $target;
 98:             }
 99: 
100:             $stocktake->fill([
101:                 'branch_id' => $data['branch_id'] ?? $stocktake->branch_id,
102:                 'location_id' => array_key_exists('location_id', $data) ? $data['location_id'] : $stocktake->location_id,
103:                 'notes' => array_key_exists('notes', $data) ? $data['notes'] : $stocktake->notes,
104:             ])->save();
105: 
106:             if (isset($data['items'])) {
107:                 $stocktake->items()->delete();
108:                 $this->syncItems($stocktake, $data['items']);
109:             }
110: 
111:             return $stocktake->load(['items.variant', 'branch', 'location', 'creator']);
112:         });
113:     }
114: 
115:     /**
116:      * الاعتماد: تحويل كل فارق غير صفري لحركة دفتر (stocktake_gain/stocktake_loss)
117:      * على on_hand في نطاق الجلسة (فرعها وموقعها)، ثم قفل الجلسة.
118:      */
119:     public function approve(Stocktake $stocktake, int $userId): Stocktake
120:     {
121:         return DB::transaction(function () use ($stocktake, $userId): Stocktake {
122:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
123:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
124:             $stocktake->load('items.variant');
125: 
126:             if (! in_array($stocktake->status, [StocktakeStatus::Draft, StocktakeStatus::InProgress], true)) {
127:                 throw new BusinessException('لا يمكن اعتماد جرد بحالة '.$stocktake->status->value.'.');
128:             }
129: 
130:             $uncounted = $stocktake->items->filter(fn ($item) => $item->counted_qty === null);
131: 
132:             if ($stocktake->items->isEmpty()) {
133:                 throw new BusinessException('لا يمكن اعتماد جرد بلا عناصر.');
134:             }
135: 
136:             if ($uncounted->isNotEmpty()) {
137:                 throw new BusinessException('لا يمكن الاعتماد: توجد عناصر لم تُعدّ بعد.');
138:             }
139: 
140:             $levels = $this->inventory->lockLevels($stocktake->items->map(fn ($item) => [
141:                 'product_variant_id' => $item->product_variant_id,
142:                 'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
143:             ])->all());
144: 
145:             // A count becomes stale after a stock change; never overwrite intervening sales/receipts.
146:             foreach ($stocktake->items as $item) {
147:                 $key = $this->inventory->levelKey([
148:                     'product_variant_id' => $item->product_variant_id,
149:                     'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
150:                 ]);
151:                 if ((int) round((float) $levels[$key]->on_hand * 10000) !== (int) round((float) $item->system_qty * 10000)) {
152:                     throw new BusinessException('تغير رصيد المخزون منذ آخر عد؛ راجع الكميات وأعد حفظ الجرد قبل الاعتماد.');
153:                 }
154:                 if ((int) round((float) $item->counted_qty * 10000) < (int) round((float) $levels[$key]->reserved * 10000) + (int) round((float) $levels[$key]->damaged * 10000)) {
155:                     throw new BusinessException('العد الفعلي أقل من المحجوز والتالف؛ راجع الحجوزات وسوِّ التالف قبل إعادة العد والاعتماد.');
156:                 }
157:             }
158: 
159:             foreach ($stocktake->items as $item) {
160:                 $difference = (float) $item->difference;
161: 
162:                 if ($difference === 0.0) {
163:                     continue;
164:                 }
165: 
166:                 $this->inventory->recordMovement([
167:                     'product_variant_id' => $item->product_variant_id,
168:                     'branch_id' => $stocktake->branch_id,
169:                     'location_id' => $stocktake->location_id,
170:                     'type' => $difference > 0 ? StockMovementType::StocktakeGain : StockMovementType::StocktakeLoss,
171:                     'affected_bucket' => StockBucket::OnHand,
172:                     'quantity' => $difference,
173:                     'unit_cost' => $item->variant?->cost_price,
174:                     'reference_type' => Stocktake::class,
175:                     'reference_id' => $stocktake->id,
176:                     'created_by' => $userId,
177:                     'notes' => 'تسوية جرد '.$stocktake->stocktake_number,
178:                 ]);
179:             }
180: 
181:             $stocktake->update([
182:                 'status' => StocktakeStatus::Approved,
183:                 'approved_by' => $userId,
184:                 'approved_at' => now(),
185:             ]);
186: 
187:             return $stocktake->load(['items.variant', 'branch', 'location']);
188:         });
189:     }
190: 
191:     public function delete(Stocktake $stocktake, int $userId): void
192:     {
193:         DB::transaction(function () use ($stocktake, $userId): void {
194:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
195:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
196: 
197:             if (! in_array($stocktake->status, [StocktakeStatus::Draft, StocktakeStatus::Cancelled], true)) {
198:                 throw new BusinessException('لا يمكن حذف جرد إلا في حالة المسودة أو الملغي.');
199:             }
200: 
201:             $stocktake->delete();
202:         });
203:     }
