205:     private function assertEditable(Stocktake $stocktake): void
206:     {
207:         if (in_array($stocktake->status, [StocktakeStatus::Approved, StocktakeStatus::Cancelled], true)) {
208:             throw new BusinessException('هذا الجرد مقفل ولا يقبل أي تعديل.');
209:         }
210:     }
211: 
212:     /**
213:      * تسجيل العناصر مع لقطة system_qty من الرصيد الحالي في نطاق الجلسة.
214:      *
215:      * @param  list<array{product_variant_id: int, counted_qty?: float|int|string|null}>  $items
216:      */
217:     private function syncItems(Stocktake $stocktake, array $items): void
218:     {
219:         $levels = StockLevel::query()->where('branch_id', $stocktake->branch_id)
220:             ->where('location_id', $stocktake->location_id)
221:             ->whereIn('product_variant_id', array_column($items, 'product_variant_id'))
222:             ->get()->keyBy('product_variant_id');
223:         foreach ($items as $item) {
224:             $level = $levels->get($item['product_variant_id']);
225: 
226:             $stocktake->items()->create([
227:                 'product_variant_id' => $item['product_variant_id'],
228:                 'system_qty' => $level ? (float) $level->on_hand : 0,
229:                 'counted_qty' => $item['counted_qty'] ?? null,
230:             ]);
231:         }
232:     }
