 67:     public function update(StockTransfer $transfer, array $data, int $userId): StockTransfer
 68:     {
 69:         return DB::transaction(function () use ($transfer, $data, $userId): StockTransfer {
 70:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
 71:             $this->assertStatus($transfer, TransferStatus::Draft, 'التعديل');
 72:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
 73:             app(BranchAccess::class)->assertBranch($userId, (int) ($data['from_branch_id'] ?? $transfer->from_branch_id));
 74: 
 75:             $fromBranch = $data['from_branch_id'] ?? $transfer->from_branch_id;
 76:             $toBranch = $data['to_branch_id'] ?? $transfer->to_branch_id;
 77:             if ((int) $fromBranch === (int) $toBranch) {
 78:                 throw new BusinessException('يجب اختلاف الفرع المرسل عن الفرع المستلم.');
 79:             }
 80:             $items = $data['items'] ?? $transfer->items->toArray();
 81:             foreach ($items as $item) {
 82:                 foreach (['from_location_id' => $fromBranch, 'to_location_id' => $toBranch] as $field => $branchId) {
 83:                     if (isset($item[$field]) && ! Location::query()->whereKey($item[$field])->where('branch_id', $branchId)->exists()) {
 84:                         throw new BusinessException('موقع التحويل لا يتبع الفرع المحدد.');
 85:                     }
 86:                 }
 87:             }
 88: 
 89:             $transfer->update([
 90:                 'from_branch_id' => $data['from_branch_id'] ?? $transfer->from_branch_id,
 91:                 'to_branch_id' => $data['to_branch_id'] ?? $transfer->to_branch_id,
 92:                 'notes' => array_key_exists('notes', $data) ? $data['notes'] : $transfer->notes,
 93:             ]);
 94: 
 95:             if (isset($data['items'])) {
 96:                 $transfer->items()->delete();
 97:                 $this->syncItems($transfer, $data['items']);
 98:             }
 99: 
100:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch', 'creator']);
101:         });
102:     }
