104:     /** الاعتماد: حجز الكميات المعتمدة في الفرع المرسل حتى لا تُباع قبل الشحن. */
105:     public function approve(StockTransfer $transfer, array $itemsPayload, int $userId): StockTransfer
106:     {
107:         return DB::transaction(function () use ($transfer, $itemsPayload, $userId): StockTransfer {
108:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
109:             $transfer->load('items.variant');
110:             $this->assertStatus($transfer, TransferStatus::Draft, 'الاعتماد');
111:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
112:             if ($transfer->items->sum(fn ($item) => (float) ($itemsPayload[$item->id] ?? $item->requested_qty)) <= 0) {
113:                 throw new BusinessException('يجب اعتماد كمية موجبة واحدة على الأقل؛ يمكن إلغاء التحويل بدلًا من اعتماده بصفر.');
114:             }
115:             $this->lockTransferLevels($transfer, true, false);
116: 
117:             foreach ($transfer->items as $item) {
118:                 $approvedQty = (float) ($itemsPayload[$item->id] ?? $item->requested_qty);
119: 
120:                 if ($approvedQty < 0 || $approvedQty > (float) $item->requested_qty) {
121:                     throw new BusinessException('الكمية المعتمدة يجب أن تكون بين صفر والكمية المطلوبة.');
122:                 }
123: 
124:                 $item->update(['approved_qty' => $approvedQty]);
125: 
126:                 if ($approvedQty > 0) {
127:                     $this->inventory->recordMovement([
128:                         'product_variant_id' => $item->product_variant_id,
129:                         'branch_id' => $transfer->from_branch_id,
130:                         'location_id' => $item->from_location_id,
131:                         'type' => StockMovementType::Reserve,
132:                         'affected_bucket' => StockBucket::Reserved,
133:                         'quantity' => $approvedQty,
134:                         'unit_cost' => $item->variant?->cost_price,
135:                         'reference_type' => StockTransfer::class,
136:                         'reference_id' => $transfer->id,
137:                         'created_by' => $userId,
138:                         'notes' => 'حجز لصالح تحويل '.$transfer->transfer_number,
139:                     ]);
140:                 }
141:             }
142: 
143:             $transfer->update(['status' => TransferStatus::Approved, 'approved_by' => $userId]);
144: 
145:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
146:         });
147:     }
