149:     /** الشحن: فك الحجز وإخراج البضاعة من المرسل، وتسجيلها "في الطريق" عند المستلم. */
150:     public function ship(StockTransfer $transfer, array $itemsPayload, int $userId): StockTransfer
151:     {
152:         return DB::transaction(function () use ($transfer, $itemsPayload, $userId): StockTransfer {
153:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
154:             $transfer->load('items.variant');
155:             $this->assertStatus($transfer, TransferStatus::Approved, 'الشحن');
156:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
157:             if ($transfer->items->sum(fn ($item) => (float) ($itemsPayload[$item->id] ?? $item->approved_qty)) <= 0) {
158:                 throw new BusinessException('يجب شحن كمية موجبة واحدة على الأقل؛ يمكن إلغاء التحويل لفك الحجز.');
159:             }
160:             $this->lockTransferLevels($transfer, true, true);
161: 
162:             foreach ($transfer->items as $item) {
163:                 $shippedQty = (float) ($itemsPayload[$item->id] ?? $item->approved_qty);
164: 
165:                 if ($shippedQty < 0 || $shippedQty > (float) $item->approved_qty) {
166:                     throw new BusinessException('الكمية المشحونة يجب أن تكون بين صفر والكمية المعتمدة.');
167:                 }
168: 
169:                 $item->update(['shipped_qty' => $shippedQty]);
170: 
171:                 if ($shippedQty <= 0) {
172:                     if ((float) $item->approved_qty > 0) {
173:                         $this->inventory->recordMovement([
174:                             'product_variant_id' => $item->product_variant_id,
175:                             'branch_id' => $transfer->from_branch_id,
176:                             'location_id' => $item->from_location_id,
177:                             'type' => StockMovementType::ReleaseReserve,
178:                             'affected_bucket' => StockBucket::Reserved,
179:                             'quantity' => -(float) $item->approved_qty,
180:                             'reference_type' => StockTransfer::class,
181:                             'reference_id' => $transfer->id,
182:                             'created_by' => $userId,
183:                             'notes' => 'فك حجز صنف غير مشحون من تحويل '.$transfer->transfer_number,
184:                         ]);
185:                     }
186: 
187:                     continue;
188:                 }
189: 
190:                 $base = [
191:                     'product_variant_id' => $item->product_variant_id,
192:                     'unit_cost' => $item->variant?->cost_price,
193:                     'reference_type' => StockTransfer::class,
194:                     'reference_id' => $transfer->id,
195:                     'created_by' => $userId,
196:                 ];
197: 
198:                 // المرسل: فك الحجز ثم إخراج فعلي
199:                 $this->inventory->recordMovement([...$base,
200:                     'branch_id' => $transfer->from_branch_id,
201:                     'location_id' => $item->from_location_id,
202:                     'type' => StockMovementType::ReleaseReserve,
203:                     'affected_bucket' => StockBucket::Reserved,
204:                     'quantity' => -$shippedQty,
205:                     'notes' => 'فك حجز عند شحن تحويل '.$transfer->transfer_number,
206:                 ]);
207:                 $this->inventory->recordMovement([...$base,
208:                     'branch_id' => $transfer->from_branch_id,
209:                     'location_id' => $item->from_location_id,
210:                     'type' => StockMovementType::TransferOut,
211:                     'affected_bucket' => StockBucket::OnHand,
212:                     'quantity' => -$shippedQty,
213:                     'notes' => 'شحن تحويل '.$transfer->transfer_number,
214:                 ]);
215: 
216:                 // الباقي المحجوز (معتمد ولم يُشحن) يرجع متاحًا للبيع
217:                 $unshipped = round((float) $item->approved_qty - $shippedQty, 4);
218:                 if ($unshipped > 0) {
219:                     $this->inventory->recordMovement([...$base,
220:                         'branch_id' => $transfer->from_branch_id,
221:                         'location_id' => $item->from_location_id,
222:                         'type' => StockMovementType::ReleaseReserve,
223:                         'affected_bucket' => StockBucket::Reserved,
224:                         'quantity' => -$unshipped,
225:                         'notes' => 'فك حجز الكمية المعتمدة غير المشحونة من تحويل '.$transfer->transfer_number,
226:                     ]);
227:                 }
228: 
229:                 // المستلم: بضاعة في الطريق
230:                 $this->inventory->recordMovement([...$base,
231:                     'branch_id' => $transfer->to_branch_id,
232:                     'location_id' => $item->to_location_id,
233:                     'type' => StockMovementType::TransferInTransit,
234:                     'affected_bucket' => StockBucket::InTransit,
235:                     'quantity' => $shippedQty,
236:                     'notes' => 'بضاعة في الطريق من تحويل '.$transfer->transfer_number,
237:                 ]);
238:             }
239: 
240:             $transfer->update(['status' => TransferStatus::Shipped, 'shipped_at' => now()]);
241: 
242:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
243:         });
244:     }
