246:     /** الاستلام: تسوية in_transit بالكامل، وإضافة المستلم فعليًا، وتسوية أي عجز كحركة مستقلة. */
247:     public function receive(StockTransfer $transfer, array $itemsPayload, int $userId): StockTransfer
248:     {
249:         return DB::transaction(function () use ($transfer, $itemsPayload, $userId): StockTransfer {
250:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
251:             $transfer->load('items.variant');
252:             $this->assertStatus($transfer, TransferStatus::Shipped, 'الاستلام');
253:             app(BranchAccess::class)->assertBranch($userId, $transfer->to_branch_id);
254:             $this->lockTransferLevels($transfer, false, true);
255: 
256:             $shortageNotes = [];
257: 
258:             foreach ($transfer->items as $item) {
259:                 $receivedQty = (float) ($itemsPayload[$item->id] ?? $item->shipped_qty);
260:                 $shippedQty = (float) $item->shipped_qty;
261: 
262:                 if ($receivedQty < 0 || $receivedQty > $shippedQty) {
263:                     throw new BusinessException('الكمية المستلمة يجب أن تكون بين صفر والكمية المشحونة.');
264:                 }
265: 
266:                 $item->update(['received_qty' => $receivedQty]);
267: 
268:                 if ($shippedQty <= 0) {
269:                     continue;
270:                 }
271: 
272:                 $base = [
273:                     'product_variant_id' => $item->product_variant_id,
274:                     'branch_id' => $transfer->to_branch_id,
275:                     'location_id' => $item->to_location_id,
276:                     'unit_cost' => $item->variant?->cost_price,
277:                     'reference_type' => StockTransfer::class,
278:                     'reference_id' => $transfer->id,
279:                     'created_by' => $userId,
280:                 ];
281: 
282:                 // خروج الجزء المستلم من "في الطريق" ودخوله الرصيد الفعلي
283:                 if ($receivedQty > 0) {
284:                     $this->inventory->recordMovement([...$base,
285:                         'type' => StockMovementType::TransferTransitRelease,
286:                         'affected_bucket' => StockBucket::InTransit,
287:                         'quantity' => -$receivedQty,
288:                         'notes' => 'استلام تحويل '.$transfer->transfer_number,
289:                     ]);
290:                     $this->inventory->recordMovement([...$base,
291:                         'type' => StockMovementType::TransferIn,
292:                         'affected_bucket' => StockBucket::OnHand,
293:                         'quantity' => $receivedQty,
294:                         'notes' => 'استلام تحويل '.$transfer->transfer_number,
295:                     ]);
296:                 }
297: 
298:                 // العجز بين المشحون والمستلم: تسوية مستقلة موثقة من رصيد "في الطريق"
299:                 $shortage = round($shippedQty - $receivedQty, 4);
300:                 if ($shortage > 0) {
301:                     $this->inventory->recordMovement([...$base,
302:                         'type' => StockMovementType::TransferShortage,
303:                         'affected_bucket' => StockBucket::InTransit,
304:                         'quantity' => -$shortage,
305:                         'notes' => 'عجز عند استلام تحويل '.$transfer->transfer_number,
306:                     ]);
307:                     $shortageNotes[] = "عجز {$shortage} وحدة في المتغير #{$item->product_variant_id}";
308:                 }
309:             }
310: 
311:             $notes = $transfer->notes;
312:             if ($shortageNotes !== []) {
313:                 $notes = trim(($notes ? $notes.' | ' : '').implode('؛ ', $shortageNotes));
314:             }
315: 
316:             $transfer->update(['status' => TransferStatus::Received, 'received_at' => now(), 'notes' => $notes]);
317: 
318:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
319:         });
320:     }
