322:     /** الإلغاء: من المسودة مباشرة، ومن المعتمد بعد فك الحجز. المشحون لا يُلغى (يُستلم). */
323:     public function cancel(StockTransfer $transfer, int $userId): StockTransfer
324:     {
325:         return DB::transaction(function () use ($transfer, $userId): StockTransfer {
326:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
327:             $transfer->load('items.variant');
328:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
329: 
330:             if ($transfer->status === TransferStatus::Approved) {
331:                 $this->lockTransferLevels($transfer, true, false);
332:                 foreach ($transfer->items as $item) {
333:                     if ((float) $item->approved_qty <= 0) {
334:                         continue;
335:                     }
336: 
337:                     $this->inventory->recordMovement([
338:                         'product_variant_id' => $item->product_variant_id,
339:                         'branch_id' => $transfer->from_branch_id,
340:                         'location_id' => $item->from_location_id,
341:                         'type' => StockMovementType::ReleaseReserve,
342:                         'affected_bucket' => StockBucket::Reserved,
343:                         'quantity' => -(float) $item->approved_qty,
344:                         'reference_type' => StockTransfer::class,
345:                         'reference_id' => $transfer->id,
346:                         'created_by' => $userId,
347:                         'notes' => 'فك حجز عند إلغاء تحويل '.$transfer->transfer_number,
348:                     ]);
349:                 }
350:             } elseif ($transfer->status !== TransferStatus::Draft) {
351:                 throw new BusinessException('لا يمكن إلغاء تحويل بحالة '.$transfer->status->value.'.');
352:             }
353: 
354:             $transfer->update(['status' => TransferStatus::Cancelled]);
355: 
356:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
357:         });
358:     }
