360:     public function delete(StockTransfer $transfer, int $userId): void
361:     {
362:         DB::transaction(function () use ($transfer, $userId): void {
363:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
364:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
365: 
366:             if (! in_array($transfer->status, [TransferStatus::Draft, TransferStatus::Cancelled], true)) {
367:                 throw new BusinessException('لا يمكن حذف تحويل إلا في حالة المسودة أو الملغي.');
368:             }
369: 
370:             $transfer->delete();
371:         });
372:     }
