374:     private function assertStatus(StockTransfer $transfer, TransferStatus $expected, string $action): void
375:     {
376:         if ($transfer->status !== $expected) {
377:             throw new BusinessException("لا يمكن تنفيذ {$action} على تحويل بحالة {$transfer->status->value}.");
378:         }
