381:     /**
382:      * @param  list<array{product_variant_id: int, from_location_id?: int|null, to_location_id?: int|null, requested_qty: float|int|string}>  $items
383:      */
384:     private function syncItems(StockTransfer $transfer, array $items): void
385:     {
386:         $this->assertDistinctItems($items);
387:         foreach ($items as $item) {
388:             $transfer->items()->create([
389:                 'product_variant_id' => $item['product_variant_id'],
390:                 'from_location_id' => $item['from_location_id'] ?? null,
391:                 'to_location_id' => $item['to_location_id'] ?? null,
392:                 'requested_qty' => $item['requested_qty'],
393:             ]);
394:         }
395:     }
396: 
397:     private function assertDistinctItems(array $items): void
398:     {
399:         $keys = array_map(fn ($item) => $item['product_variant_id'].':'.($item['from_location_id'] ?? 0).':'.($item['to_location_id'] ?? 0), $items);
400:         if (count(array_unique($keys)) !== count($keys)) {
401:             throw new BusinessException('لا يجوز تكرار نفس الصنف وموقعي الإرسال والاستلام داخل التحويل.');
402:         }
403:     }
404: 
405:     private function lockTransferLevels(StockTransfer $transfer, bool $source, bool $destination): void
406:     {
407:         $keys = [];
408:         foreach ($transfer->items as $item) {
409:             if ($source) {
410:                 $keys[] = ['branch_id' => $transfer->from_branch_id, 'location_id' => $item->from_location_id, 'product_variant_id' => $item->product_variant_id];
411:             }
412:             if ($destination) {
413:                 $keys[] = ['branch_id' => $transfer->to_branch_id, 'location_id' => $item->to_location_id, 'product_variant_id' => $item->product_variant_id];
414:             }
415:         }
416:         $this->inventory->lockLevels($keys);
417:     }
