  5: namespace Tests\Feature\Admin\Inventory;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Branch;
 11: use App\Models\ProductVariant;
 12: use App\Models\StockLevel;
 13: use App\Models\StockMovement;
 14: use App\Models\User;
 15: use App\Services\InventoryService;
 16: use Database\Seeders\SettingSeeder;
 17: use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
 18: use Illuminate\Support\Facades\Auth;
 19: use Illuminate\Testing\TestResponse;
 20: use LogicException;
 21: use Spatie\Permission\Models\Permission;
 22: use Tests\TestCase;
 23: 
 24: class InventorySystemTest extends TestCase
 25: {
 26:     use LazilyRefreshDatabase;
 27: 
 28:     private const ALL_PERMISSIONS = [
 29:         'inventory.view', 'inventory.adjust',
 30:         'transfers.view', 'transfers.create', 'transfers.update', 'transfers.delete',
 31:         'transfers.approve', 'transfers.ship', 'transfers.receive',
 32:         'stocktakes.view', 'stocktakes.create', 'stocktakes.update', 'stocktakes.delete', 'stocktakes.approve',
 33:     ];
 34: 
 35:     protected function setUp(): void
 36:     {
 37:         parent::setUp();
 38:         $this->seed(SettingSeeder::class); // مفاتيح الترقيم لازمة لتوليد أرقام الحركات والمستندات
 39:     }
 40: 
 41:     // ---------- InventoryService / Ledger ----------
 42: 
 43:     public function test_record_movement_creates_level_and_ledger_entry(): void
 44:     {
 45:         $admin = $this->staffWithPermissions(self::ALL_PERMISSIONS);
 46:         $variant = ProductVariant::factory()->create();
 47:         $branch = Branch::factory()->create();
 48: 
 49:         $movement = app(InventoryService::class)->recordMovement([
 50:             'product_variant_id' => $variant->id,
 51:             'branch_id' => $branch->id,
 52:             'type' => StockMovementType::AdjustmentIn,
 53:             'affected_bucket' => StockBucket::OnHand,
 54:             'quantity' => 10,
 55:             'created_by' => $admin->id,
 56:         ]);
 57: 
 58:         $this->assertSame('10.0000', $movement->balance_after);
 59:         $this->assertSame('0.0000', $movement->balance_before);
 60:         $this->assertStringStartsWith('MOV-', $movement->reference_number);
 61: 
 62:         $level = StockLevel::query()->where('product_variant_id', $variant->id)->where('branch_id', $branch->id)->first();
 63:         $this->assertSame('10.0000', $level->on_hand);
 64:         $this->assertSame(10.0, $level->available);
 65:     }
 66: 
 67:     public function test_record_movement_rejects_zero_quantity_and_negative_balance(): void
 68:     {
 69:         $variant = ProductVariant::factory()->create();
 70:         $branch = Branch::factory()->create();
 71:         $service = app(InventoryService::class);
 72:         $base = ['product_variant_id' => $variant->id, 'branch_id' => $branch->id, 'created_by' => User::factory()->create()->id];
 73: 
 74:         try {
 75:             $service->recordMovement([...$base, 'type' => 'adjustment_in', 'affected_bucket' => 'on_hand', 'quantity' => 0]);
 76:             $this->fail('zero quantity must be rejected');
 77:         } catch (BusinessException) {
 78:             $this->addToAssertionCount(1);
 79:         }
 80: 
 81:         $this->expectException(BusinessException::class);
 82:         $service->recordMovement([...$base, 'type' => 'adjustment_out', 'affected_bucket' => 'on_hand', 'quantity' => -1]);
 83:     }
 84: 
 85:     public function test_reserve_cannot_exceed_available(): void
 86:     {
 87:         $variant = ProductVariant::factory()->create();
 88:         $branch = Branch::factory()->create();
 89:         $service = app(InventoryService::class);
 90:         $base = ['product_variant_id' => $variant->id, 'branch_id' => $branch->id, 'created_by' => User::factory()->create()->id];
 91: 
 92:         $service->recordMovement([...$base, 'type' => 'adjustment_in', 'affected_bucket' => 'on_hand', 'quantity' => 5]);
 93: 
 94:         $this->expectException(BusinessException::class);
 95:         $service->recordMovement([...$base, 'type' => 'reserve', 'affected_bucket' => 'reserved', 'quantity' => 6]);
 96:     }
 97: 
 98:     public function test_movement_ledger_is_immutable(): void
 99:     {
100:         $variant = ProductVariant::factory()->create();
101:         $branch = Branch::factory()->create();
102: 
103:         $movement = app(InventoryService::class)->recordMovement([
104:             'product_variant_id' => $variant->id,
105:             'branch_id' => $branch->id,
106:             'type' => 'adjustment_in',
107:             'affected_bucket' => 'on_hand',
108:             'quantity' => 3,
109:             'created_by' => User::factory()->create()->id,
110:         ]);
111: 
112:         try {
113:             $movement->update(['quantity' => 99]);
114:             $this->fail('ledger update must be blocked');
115:         } catch (LogicException) {
