208:     public function test_transfer_full_lifecycle_with_shortage(): void
209:     {
210:         $admin = $this->staffWithPermissions(self::ALL_PERMISSIONS);
211:         $token = $admin->createToken('test')->plainTextToken;
212:         $variant = ProductVariant::factory()->create();
