301:     private function staffWithPermissions(array $permissions): User
302:     {
303:         foreach ($permissions as $permission) {
304:             Permission::findOrCreate($permission, 'staff');
305:         }
306:         $staff = User::factory()->create();
307:         $staff->givePermissionTo($permissions);
308: 
309:         return $staff;
310:     }
