34:         foreach ([
35:             'admin.auth.me',
36:             'admin.branches.index',
37:             'admin.branches.locations.index',
38:             'admin.users.index',
39:             'admin.roles.index',
40:             'admin.permissions.index',
41:             'admin.settings.index',
