 37:         Route::get('/_test-auth/staff', fn (Request $request) => [
 38:             'id' => $request->user()->getKey(),
 39:             'model' => $request->user()::class,
 40:         ])->middleware('auth.staff');
 41: 
 42:         Route::get('/_test-auth/customer', fn (Request $request) => [
 43:             'id' => $request->user()->getKey(),
