 54:             'model' => $request->user()::class,
 55:         ])->middleware('auth.supplier');
 56: 
 57:         Route::get('/_test-auth/staff-role', fn () => ['ok' => true])
 58:             ->middleware(['auth.staff', 'role:manager']);
 59: 
 60:         Route::get('/_test-auth/staff-permission', fn () => ['ok' => true])
 61:             ->middleware(['auth.staff', 'permission:inventory.read']);
 62:     }
