 64:     public function test_returns_403_for_inactive_staff_and_authenticates_active_staff(): void
 65:     {
 66:         $activeStaff = User::factory()->create(['is_active' => true]);
 67:         $activeToken = $activeStaff->createToken('test')->plainTextToken;
 68: 
 69:         $this->requestWithToken($activeToken, '/_test-auth/staff')
 70:             ->assertOk()
 71:             ->assertJsonPath('model', User::class);
 72: 
 73:         $inactiveStaff = User::factory()->create(['is_active' => false]);
 74:         $inactiveToken = $inactiveStaff->createToken('test')->plainTextToken;
 75: 
 76:         $this->requestWithToken($inactiveToken, '/_test-auth/staff')->assertForbidden();
 77:     }
