 79:     public function test_returns_403_for_blocked_customers_but_allows_pending_customers(): void
 80:     {
 81:         $pendingCustomer = $this->createCustomer(status: CustomerStatus::Pending);
 82:         $pendingToken = $pendingCustomer->createToken('test')->plainTextToken;
 83: 
 84:         $this->requestWithToken($pendingToken, '/_test-auth/customer')
 85:             ->assertOk()
 86:             ->assertJsonPath('model', Customer::class);
 87: 
 88:         $blockedCustomer = $this->createCustomer(status: CustomerStatus::Blocked);
 89:         $blockedToken = $blockedCustomer->createToken('test')->plainTextToken;
 90: 
 91:         $this->requestWithToken($blockedToken, '/_test-auth/customer')->assertForbidden();
 92: 
 93:         $rejectedCustomer = $this->createCustomer(status: CustomerStatus::Rejected);
 94:         $rejectedToken = $rejectedCustomer->createToken('test')->plainTextToken;
 95: 
 96:         $this->requestWithToken($rejectedToken, '/_test-auth/customer')->assertForbidden();
 97:     }
