 20: class BranchController extends Controller
 21: {
 22:     public function index(Request $request): AnonymousResourceCollection
 23:     {
 24:         $validated = $request->validate([
 25:             'per_page' => ['sometimes', 'integer', 'min:1', 'max:100'],
 26:         ]);
 27: 
 28:         $branches = Branch::query()
 29:             ->withCount(['locations', 'users'])
 30:             ->orderBy('id')
 31:             ->paginate($validated['per_page'] ?? 15)
 32:             ->withQueryString();
 33: 
 34:         return BranchResource::collection($branches);
 35:     }
 36: 
 37:     public function store(StoreBranchRequest $request): JsonResponse
 38:     {
 39:         $branch = Branch::query()->create($request->validated());
 40:         $branch->loadCount(['locations', 'users']);
 41: 
 42:         return BranchResource::make($branch)->response()->setStatusCode(201);
 43:     }
 44: 
 45:     public function show(Branch $branch): BranchResource
 46:     {
 47:         return BranchResource::make($branch->loadCount(['locations', 'users']));
 48:     }
 49: 
 50:     public function update(UpdateBranchRequest $request, Branch $branch): BranchResource
 51:     {
 52:         $branch->update($request->validated());
 53: 
 54:         return BranchResource::make($branch->loadCount(['locations', 'users']));
 55:     }
 56: 
 57:     public function destroy(Branch $branch): JsonResponse|Response
 58:     {
 59:         $inventoryTables = $this->inventoryMovementTables();
 60: 
 61:         try {
 62:             $deleted = DB::transaction(function () use ($branch, $inventoryTables): bool {
 63:                 $lockedBranch = Branch::query()
 64:                     ->whereKey($branch->getKey())
 65:                     ->lockForUpdate()
 66:                     ->firstOrFail();
 67: 
 68:                 if ($lockedBranch->users()->exists() || $this->hasInventoryMovements($lockedBranch, $inventoryTables)) {
 69:                     return false;
 70:                 }
 71: 
 72:                 $lockedBranch->delete();
 73: 
 74:                 return true;
 75:             });
 76:         } catch (QueryException $exception) {
 77:             if (! $this->isIntegrityConstraintViolation($exception)) {
 78:                 throw $exception;
 79:             }
 80: 
 81:             return $this->conflictResponse();
 82:         }
 83: 
 84:         if (! $deleted) {
 85:             return $this->conflictResponse();
 86:         }
 87: 
 88:         return response()->noContent();
 89:     }
 90: 
 91:     /**
 92:      * @return array<string, list<string>>
 93:      */
 94:     private function inventoryMovementTables(): array
 95:     {
 96:         $tables = [];
 97: 
 98:         foreach (['inventory_movements', 'stock_movements', 'inventory_transactions', 'stock_transactions'] as $table) {
 99:             if (! Schema::hasTable($table)) {
100:                 continue;
101:             }
102: 
103:             $columns = [];
104: 
105:             foreach (['branch_id', 'location_id'] as $column) {
106:                 if (Schema::hasColumn($table, $column)) {
107:                     $columns[] = $column;
108:                 }
109:             }
110: 
111:             if ($columns !== []) {
112:                 $tables[$table] = $columns;
113:             }
114:         }
115: 
116:         return $tables;
117:     }
118: 
119:     /**
120:      * @param  array<string, list<string>>  $tables
121:      */
122:     private function hasInventoryMovements(Branch $branch, array $tables): bool
123:     {
124:         foreach ($tables as $table => $columns) {
125:             if (in_array('branch_id', $columns, true) && DB::table($table)->where('branch_id', $branch->getKey())->exists()) {
126:                 return true;
127:             }
128: 
129:             if (in_array('location_id', $columns, true)) {
130:                 $locationIds = $branch->locations()->select('locations.id');
131: 
132:                 if (DB::table($table)->whereIn('location_id', $locationIds)->exists()) {
133:                     return true;
134:                 }
135:             }
136:         }
137: 
138:         return false;
139:     }
140: 
141:     private function isIntegrityConstraintViolation(QueryException $exception): bool
142:     {
143:         $sqlState = (string) ($exception->errorInfo[0] ?? $exception->getCode());
144: 
145:         return in_array($sqlState, ['23000', '23503'], true);
146:     }
147: 
148:     private function conflictResponse(): JsonResponse
149:     {
150:         return response()->json([
151:             'message' => 'لا يمكن حذف الفرع لارتباطه بموظفين أو حركات مخزنية.',
152:         ], 409);
153:     }
