 96:     public function test_branch_cannot_be_deleted_while_stock_movements_reference_it(): void
 97:     {
 98:         $createdTemporaryTable = ! Schema::hasTable('stock_movements');
 99: 
100:         if ($createdTemporaryTable && in_array(DB::connection()->getDriverName(), ['mysql', 'mariadb'], true)) {
101:             $this->markTestSkipped('A MySQL test fixture needs a real stock_movements migration to avoid implicit DDL commits.');
102:         }
103: 
104:         if ($createdTemporaryTable) {
105:             Schema::create('stock_movements', function (Blueprint $table): void {
106:                 $table->id();
107:                 $table->foreignId('branch_id')->constrained()->restrictOnDelete();
108:             });
109:         }
110: 
111:         try {
112:             $branch = Branch::factory()->create();
113:             $admin = $this->staffWithPermission('branches.manage');
114:             if ($createdTemporaryTable) {
115:                 DB::table('stock_movements')->insert(['branch_id' => $branch->id]);
116:             } else {
