128:                 ->assertStatus(409);
129: 
130:             $this->assertDatabaseHas('branches', ['id' => $branch->id]);
131:             $this->assertDatabaseHas('stock_movements', ['branch_id' => $branch->id]);
132:         } finally {
133:             if ($createdTemporaryTable) {
134:                 Schema::dropIfExists('stock_movements');
135:             }
136:         }
137: 
138:         if ($createdTemporaryTable) {
139:             $this->assertFalse(Schema::hasTable('stock_movements'));
140:         }
