 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Api\V1\Admin\AdminLoginRequest;
 9: use App\Http\Resources\Api\V1\Admin\UserResource;
10: use App\Models\User;
11: use Illuminate\Http\JsonResponse;
12: use Illuminate\Http\Request;
13: use Illuminate\Http\Resources\Json\JsonResource;
14: use Illuminate\Http\Response;
15: use Illuminate\Support\Facades\Hash;
16: use Illuminate\Support\Facades\RateLimiter;
17: use Illuminate\Support\Str;
18: 
19: class AuthController extends Controller
20: {
21:     private const DUMMY_PASSWORD_HASH = '$2y$12$dRibbzvWAKqkXBRPna4QCuri7dR8TKHRGDIt.RsplFZRfRcJzmPlq';
22: 
23:     public function login(AdminLoginRequest $request): JsonResource|JsonResponse
24:     {
25:         $credentials = $request->validated();
26:         $user = User::query()
27:             ->whereRaw('LOWER(email) = ?', [$credentials['email']])
28:             ->first();
29:         $storedHash = $user instanceof User ? $user->password : self::DUMMY_PASSWORD_HASH;
30:         $passwordMatches = Hash::check($credentials['password'], $storedHash);
31: 
32:         if (! $user instanceof User || ! $user->is_active || ! $passwordMatches) {
33:             return response()->json([
34:                 'message' => 'بيانات تسجيل الدخول غير صحيحة أو الحساب غير نشط.',
35:             ], 401);
36:         }
37: 
38:         $emailKey = hash('sha256', Str::transliterate(Str::lower(trim($credentials['email']))));
39:         RateLimiter::clear('admin-login-email:'.$emailKey);
40:         RateLimiter::clear('admin-login-email-hour:'.$emailKey);
41: 
42:         $user->load(['branch', 'roles.permissions', 'permissions']);
43:         $token = $user->createToken('staff-token')->plainTextToken;
44: 
45:         return UserResource::make($user)->additional(['token' => $token]);
46:     }
47: 
48:     public function me(Request $request): JsonResource
49:     {
50:         $user = $request->user('staff');
51: 
52:         abort_unless($user instanceof User, 403);
53: 
54:         $user->load(['branch', 'roles.permissions', 'permissions']);
55: 
56:         return UserResource::make($user);
57:     }
58: 
59:     public function logout(Request $request): Response
60:     {
61:         $request->user('staff')?->currentAccessToken()?->delete();
62: 
63:         return response()->noContent();
64:     }
