  5: namespace App\Services;
  6: 
  7: use App\Exceptions\BusinessException;
  8: use App\Models\Setting;
  9: use Illuminate\Support\Facades\Cache;
 10: use Illuminate\Support\Facades\DB;
 11: use InvalidArgumentException;
 12: use JsonException;
 13: 
 14: class SettingService
 15: {
 16:     private const CACHE_KEY = 'app_settings_static';
 17: 
 18:     private const CACHE_TTL_SECONDS = 3600;
 19: 
 20:     /** @var list<string> */
 21:     private const NUMBERING_COUNTER_KEYS = [
 22:         'invoice_next_number',
 23:         'order_next_number',
 24:         'purchase_order_next_number',
 25:         'quotation_next_number',
 26:         'movement_next_number',
 27:         'transfer_next_number',
 28:         'stocktake_next_number',
 29:     ];
 30: 
 31:     /**
 32:      * Return all settings grouped by their group name, with values cast to their declared types.
 33:      * Numbering counters are read fresh because they change for every generated document number.
 34:      *
 35:      * @return array<string, array<string, mixed>>
 36:      */
 37:     public function getAllGrouped(): array
 38:     {
 39:         $grouped = Cache::remember(self::CACHE_KEY, self::CACHE_TTL_SECONDS, function (): array {
 40:             return Setting::query()
 41:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
 42:                 ->orderBy('group')
 43:                 ->orderBy('key')
 44:                 ->get()
 45:                 ->groupBy('group')
 46:                 ->map(fn ($settings): array => $settings
 47:                     ->mapWithKeys(fn (Setting $setting): array => [
 48:                         $setting->key => $this->castValue($setting->value, $setting->type),
 49:                     ])
 50:                     ->all())
 51:                 ->all();
 52:         });
 53: 
 54:         $counters = Setting::query()
 55:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
 56:             ->orderBy('key')
 57:             ->get()
 58:             ->mapWithKeys(fn (Setting $setting): array => [
 59:                 $setting->key => $this->castValue($setting->value, $setting->type),
 60:             ])
 61:             ->all();
 62: 
 63:         if (isset($counters['movement_next_number'])) {
 64:             $counters['movement_next_number'] = $this->nextMovementNumber();
 65:         }
 66: 
 67:         if ($counters !== []) {
 68:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
 69:             ksort($grouped['numbering']);
 70:         }
 71: 
 72:         return $grouped;
 73:     }
