 75:     public function get(string $key, mixed $default = null): mixed
 76:     {
 77:         foreach ($this->getAllGrouped() as $settings) {
 78:             if (array_key_exists($key, $settings)) {
 79:                 return $settings[$key];
 80:             }
 81:         }
 82: 
 83:         return $default;
 84:     }
