 86:     /**
 87:      * Update a flat key/value map atomically and invalidate the cached settings after commit.
 88:      *
 89:      * @param  array<string, mixed>  $settings
 90:      *
 91:      * @throws JsonException
 92:      */
 93:     public function updateBatch(array $settings): void
 94:     {
 95:         DB::transaction(function () use ($settings): void {
 96:             $lockedSettings = Setting::query()
 97:                 ->whereIn('key', array_keys($settings))
 98:                 ->orderBy('key')
 99:                 ->lockForUpdate()
100:                 ->get()
101:                 ->keyBy('key');
102: 
103:             $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());
104: 
105:             if ($missingKeys !== []) {
106:                 throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
107:             }
108: 
109:             foreach ($settings as $key => $value) {
110:                 /** @var Setting $setting */
111:                 $setting = $lockedSettings->get($key);
112: 
113:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
114:                     $value = max($this->counterValue($setting->value), $this->counterValue($value));
115:                     if ($key === 'movement_next_number') {
116:                         // Configuration changes are rare; lock the sequence only here, never per movement.
117:                         DB::statement('ALTER SEQUENCE stock_movement_number_seq INCREMENT BY 1');
118:                         $value = max($value, $this->nextMovementNumber());
119:                         DB::statement('ALTER SEQUENCE stock_movement_number_seq RESTART WITH '.$value);
120:                     }
121:                 }
122: 
123:                 $setting->value = $value === null && str_ends_with($key, '_prefix')
124:                     ? ''
125:                     : $this->serializeValue($value, $setting->type);
126:                 $setting->save();
127:             }
128: 
129:             DB::afterCommit(fn () => $this->clearCache());
130:         }, attempts: 3);
131:     }
132: 
133:     /**
134:      * Atomically return and increment the next document number for the requested type.
135:      *
136:      * @throws JsonException
137:      */
138:     public function generateNextNumber(string $type): string
139:     {
140:         if ($type === 'movement') {
141:             $settings = Setting::query()->whereIn('key', ['movement_prefix', 'movement_padding'])->pluck('value', 'key');
142:             if (! $settings->has('movement_prefix') || ! $settings->has('movement_padding')) {
143:                 throw new InvalidArgumentException('Movement numbering settings are not initialized.');
144:             }
145:             $number = DB::selectOne("SELECT nextval('stock_movement_number_seq') AS number")->number;
146: 
147:             return $settings['movement_prefix'].str_pad((string) $number, max(0, (int) $settings['movement_padding']), '0', STR_PAD_LEFT);
148:         }
149:         $definitions = [
150:             'invoice' => ['prefix' => 'invoice_prefix', 'next' => 'invoice_next_number', 'padding' => 'invoice_padding'],
151:             'order' => ['prefix' => 'order_prefix', 'next' => 'order_next_number', 'padding' => 'order_padding'],
152:             'purchase_order' => ['prefix' => 'purchase_order_prefix', 'next' => 'purchase_order_next_number', 'padding' => 'purchase_order_padding'],
153:             'quotation' => ['prefix' => 'quotation_prefix', 'next' => 'quotation_next_number', 'padding' => 'quotation_padding'],
154:             'transfer' => ['prefix' => 'transfer_prefix', 'next' => 'transfer_next_number', 'padding' => 'transfer_padding'],
155:             'stocktake' => ['prefix' => 'stocktake_prefix', 'next' => 'stocktake_next_number', 'padding' => 'stocktake_padding'],
156:         ];
157: 
158:         if (! isset($definitions[$type])) {
159:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
160:         }
161: 
162:         $definition = $definitions[$type];
163:         $keys = array_values(array_filter([
164:             $definition['prefix'],
165:             $definition['next'],
166:             $definition['padding'],
167:         ]));
168: 
169:         return DB::transaction(function () use ($definition, $keys): string {
170:             $settings = Setting::query()
171:                 ->whereIn('key', $keys)
172:                 ->orderBy('key')
173:                 ->lockForUpdate()
174:                 ->get()
175:                 ->keyBy('key');
176: 
177:             foreach ($keys as $key) {
178:                 if (! $settings->has($key)) {
179:                     throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
180:                 }
181:             }
182: 
183:             $prefix = (string) $settings->get($definition['prefix'])->value;
184:             $nextSetting = $settings->get($definition['next']);
185:             $nextValue = $this->counterValue($nextSetting->value);
186:             $padding = max(0, (int) $settings->get($definition['padding'])->value);
187: 
188:             $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
189:             $nextSetting->value = (string) ($nextValue + 1);
190:             $nextSetting->save();
191: 
192:             return $formatted;
193:         }, attempts: 3);
194:     }
195: 
196:     public function clearCache(): void
197:     {
198:         Cache::forget(self::CACHE_KEY);
199:     }
200: 
201:     private function nextMovementNumber(): int
202:     {
203:         $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');
204: 
205:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
206:     }
207: 
208:     private function counterValue(mixed $value): int
209:     {
210:         $number = (is_int($value) || is_string($value))
211:             ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
212:             : false;
213:         if ($number === false) {
214:             throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
215:         }
216: 
217:         return $number;
218:     }
219: 
220:     private function castValue(?string $value, string $type): mixed
221:     {
222:         if ($value === null) {
223:             return null;
224:         }
225: 
226:         return match ($type) {
227:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
228:             'integer' => (int) $value,
229:             'float' => (float) $value,
230:             'json' => json_decode($value, true, 512, JSON_THROW_ON_ERROR),
231:             default => $value,
232:         };
233:     }
234: 
235:     /** @throws JsonException */
236:     private function serializeValue(mixed $value, string $type): ?string
237:     {
238:         if ($value === null) {
239:             return null;
240:         }
241: 
242:         if ($type === 'json') {
243:             return json_encode($value, JSON_THROW_ON_ERROR);
244:         }
245: 
246:         if ($type === 'boolean') {
247:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
248:         }
249: 
250:         return (string) $value;
251:     }
